function withEnvSnapshot(): Record<
	(typeof envKeys)[number],
	string | undefined
> {
	return {
		CLINE_DATA_DIR: process.env.CLINE_DATA_DIR,
		CLINE_LOG_PATH: process.env.CLINE_LOG_PATH,
		CLINE_LOG_LEVEL: process.env.CLINE_LOG_LEVEL,
