	};
}

function restoreEnv(
	snapshot: Record<(typeof envKeys)[number], string | undefined>,
): void {
	for (const key of envKeys) {
		const value = snapshot[key];
		if (value === undefined) {
			delete process.env[key];
			continue;
		}
		process.env[key] = value;
	}
}

