import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import { createDesktopLoggerAdapter, DESKTOP_LOG_MAX_BYTES } from "./logging";

const originalEnv = {
	CLINE_LOG_ENABLED: process.env.CLINE_LOG_ENABLED,
	CLINE_LOG_LEVEL: process.env.CLINE_LOG_LEVEL,
	CLINE_LOG_NAME: process.env.CLINE_LOG_NAME,
	CLINE_LOG_PATH: process.env.CLINE_LOG_PATH,
};

afterEach(() => {
	for (const [key, value] of Object.entries(originalEnv)) {
		if (value === undefined) delete process.env[key];
		else process.env[key] = value;
	}
});

describe("desktop sidecar logging", () => {
	it("writes structured SDK logs to the configured file", () => {
		const directory = mkdtempSync(join(tmpdir(), "cline-code-logging-"));
		const destination = join(directory, "sidecar.log");
		process.env.CLINE_LOG_PATH = destination;
		process.env.CLINE_LOG_LEVEL = "debug";
		delete process.env.CLINE_LOG_ENABLED;

		try {
			const adapter = createDesktopLoggerAdapter();
			adapter.core.debug("desktop runtime event", { sessionId: "session-1" });
			adapter.dispose();

			const contents = readFileSync(destination, "utf8");
			expect(contents).toContain("desktop runtime event");
			expect(contents).toContain('"sessionId":"session-1"');
			expect(adapter.runtimeConfig.name).toBe("cline-code.sidecar");
		} finally {
			rmSync(directory, { recursive: true, force: true });
		}
	});

	it("warns once before falling back to stderr when the log file cannot open", () => {
		const directory = mkdtempSync(join(tmpdir(), "cline-code-fallback-"));
		process.env.CLINE_LOG_PATH = directory;
		delete process.env.CLINE_LOG_ENABLED;
		const stderr = vi.spyOn(process.stderr, "write").mockReturnValue(true);

		try {
			const adapter = createDesktopLoggerAdapter();
			adapter.dispose();

			expect(stderr).toHaveBeenCalledWith(
				expect.stringContaining("Unable to open log file"),
			);
			expect(stderr).toHaveBeenCalledWith(
				expect.stringContaining("falling back to stderr"),
			);
		} finally {
			stderr.mockRestore();
			rmSync(directory, { recursive: true, force: true });
		}
	});

	it("rotates the active log before a write exceeds the size limit", () => {
		const directory = mkdtempSync(join(tmpdir(), "cline-code-rotation-"));
		const destination = join(directory, "sidecar.log");
		process.env.CLINE_LOG_PATH = destination;
		delete process.env.CLINE_LOG_ENABLED;

		try {
			mkdirSync(directory, { recursive: true });
			writeFileSync(destination, "");
			truncateSync(destination, DESKTOP_LOG_MAX_BYTES - 1);
			const adapter = createDesktopLoggerAdapter();
			adapter.core.log("rotate before writing this entry");
			adapter.dispose();

			expect(statSync(destination).size).toBeLessThan(1_024);
			expect(readFileSync(destination, "utf8")).toContain(
				"rotate before writing this entry",
			);
		} finally {
			rmSync(directory, { recursive: true, force: true });
		}
	});
});

package io.kestra.core.http.client.apache;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.stream.Collectors;

import org.apache.hc.core5.http.Header;
import org.apache.hc.core5.http.HttpEntityContainer;

import io.kestra.core.http.HttpService;

import jakarta.annotation.Nullable;

public abstract class AbstractLoggingInterceptor {
    protected static String buildHeadersEntry(String type, Header[] headers) {
        return type + " headers:" +
            (headers.length == 0 ? " null"
                : "\n    " + Arrays.stream(headers)
                    .map(header -> header.getName() + ": " + header.getValue())
                    .collect(Collectors.joining("\n    ")));
    }

    protected static String buildEntityEntry(String type, @Nullable HttpEntityContainer httpEntityContainer) throws IOException {
        if (httpEntityContainer != null && httpEntityContainer.getEntity() != null) {
            HttpService.HttpEntityCopy copy = HttpService.copy(httpEntityContainer.getEntity());
            httpEntityContainer.setEntity(copy);

            return type + " payload:" +
                "\n    " + new String(copy.getBody(), StandardCharsets.UTF_8);
        } else {
            return type + " payload: null";
        }
    }
}

package io.kestra.core.http.client.apache;

import java.io.IOException;

import org.apache.commons.lang3.ArrayUtils;
import org.apache.hc.core5.http.*;
import org.apache.hc.core5.http.protocol.HttpContext;
import org.slf4j.Logger;

import io.kestra.core.http.HttpService;
import io.kestra.core.http.client.configurations.HttpConfiguration;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public class LoggingRequestInterceptor extends AbstractLoggingInterceptor implements HttpRequestInterceptor {
    private Logger logger;
    private HttpConfiguration.LoggingType[] logs;

    @Override
    public void process(HttpRequest request, EntityDetails entity, HttpContext context) throws HttpException, IOException {
        if (logger.isDebugEnabled() && ArrayUtils.contains(logs, HttpConfiguration.LoggingType.REQUEST_HEADERS)) {
            logger.debug(buildRequestEntry(request));
            logger.debug(buildHeadersEntry("request", request.getHeaders()));
        }

        if (logger.isTraceEnabled() && ArrayUtils.contains(logs, HttpConfiguration.LoggingType.REQUEST_BODY)) {
            logger.trace(buildEntityEntry("request", request instanceof ClassicHttpRequest classicHttpRequest ? classicHttpRequest : null));
        }
    }

    private String buildRequestEntry(HttpRequest request) {
        return "request:" +
            "\n    method: " + request.getMethod() +
            "\n    uri: " + HttpService.safeURI(request);
    }
}

package io.kestra.core.http.client.apache;

import java.io.IOException;

import org.apache.commons.lang3.ArrayUtils;
import org.apache.hc.core5.http.*;
import org.apache.hc.core5.http.protocol.HttpContext;
import org.slf4j.Logger;

import io.kestra.core.http.client.configurations.HttpConfiguration;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public class LoggingResponseInterceptor extends AbstractLoggingInterceptor implements HttpResponseInterceptor {
    private Logger logger;
    private HttpConfiguration.LoggingType[] logs;

    @Override
    public void process(HttpResponse response, EntityDetails entity, HttpContext context) throws HttpException, IOException {
        if (logger.isDebugEnabled() && ArrayUtils.contains(logs, HttpConfiguration.LoggingType.RESPONSE_HEADERS)) {
            logger.debug(buildResponseEntry(response));
            logger.debug(buildHeadersEntry("response", response.getHeaders()));
        }

        if (logger.isTraceEnabled() && ArrayUtils.contains(logs, HttpConfiguration.LoggingType.RESPONSE_BODY)) {
            logger.trace(buildEntityEntry("response", response instanceof ClassicHttpResponse classicHttpResponse ? classicHttpResponse : null));
        }
    }

    private static String buildResponseEntry(HttpResponse response) {
        return "response:" +
            "\n    reason: " + response.getReasonPhrase();
    }
}

const testTransferData = { "application/x-trix-feature-detection": "test" }

export const dataTransferIsPlainText = function(dataTransfer) {
  const text = dataTransfer.getData("text/plain")
  const html = dataTransfer.getData("text/html")

  if (text && html) {
    const { body } = new DOMParser().parseFromString(html, "text/html")
    if (body.textContent === text) {
      return !body.querySelector("*")
    }
  } else {
    return text?.length
  }
}

export const dataTransferIsMsOfficePaste = ({ dataTransfer }) => {
  return dataTransfer.types.includes("Files") &&
    dataTransfer.types.includes("text/html") &&
    dataTransfer.getData("text/html").includes("urn:schemas-microsoft-com:office:office")
}

export const dataTransferIsWritable = function(dataTransfer) {
  if (!dataTransfer?.setData) return false

  for (const key in testTransferData) {
    const value = testTransferData[key]

    try {
      dataTransfer.setData(key, value)
      if (!dataTransfer.getData(key) === value) return false
    } catch (error) {
      return false
    }
  }
  return true
}

export const keyEventIsKeyboardCommand = (function() {
  if (/Mac|^iP/.test(navigator.platform)) {
    return (event) => event.metaKey
  } else {
    return (event) => event.ctrlKey
  }
})()

export function shouldRenderInmmediatelyToDealWithIOSDictation(inputEvent) {
  if (/iPhone|iPad/.test(navigator.userAgent)) {
    // Handle garbled content and duplicated newlines when using dictation on iOS 18+. Upon dictation completion, iOS sends
    // the list of insertText / insertParagraph events in a quick sequence. If we don't render
    // the editor synchronously, the internal range fails to update and results in garbled content or duplicated newlines.
    //
    // This workaround is necessary because iOS doesn't send composing events as expected while dictating:
    // https://bugs.webkit.org/show_bug.cgi?id=261764
    return !inputEvent.inputType || inputEvent.inputType === "insertParagraph"
  } else {
    return false
  }
}
